INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('2c96f6ed-67dc-5a98-aeda-51ac8409822a', 'cbe452a6-c658-5477-92ae-e07eb374dab5', 'tr', $h$H 827$h$, $h$h-827-2$h$, $h$Boya Tabancaları – Profesyonel ve Endüstriyel Boya Uygulamaları$h$, $h$<div> <p><strong>Boya tabancaları</strong>, boya veya kaplama malzemesini yüzeye püskürtmek için kullanılan profesyonel el aletleridir. Farklı tipleriyle (airless, HVLP, klasik püskürtme vb.) boya tabancaları, hem büyük yüzeylerde hem de detaylı işleri hızlı, eşit ve ekonomik bir şekilde yapmanızı sağlar.</p><p>HD Marine boya tabancaları, marin ve endüstriyel uygulamalarda yüksek performans ve kaliteyi bir arada sunan güçlü ekipmanlardır. Bu tabancalar, hem profesyonel boya ustaları hem de teknik ekipler için idealdir.</p> </div><div> <ul><li>Endüstriyel tesis boya işleri</li><li>Gemi / marin yüzey boya uygulamaları</li><li>İnşaat ve dekorasyon projeleri</li><li>Metal, ahşap, beton yüzeyler</li><li>Seri üretim ve büyük boyama hatları</li></ul><p>Boya tabancaları, <strong>hızlı kaplama</strong>, <strong>eşit boya dağılımı</strong> ve <strong>daha az boya israfı</strong> gibi avantajlarla boya sürecini daha verimli hale getirir.</p> </div><div> <ul><li><p>✔ <strong>Yüksek kaplama verimliliği:</strong> Mükemmel kaplama kalitesi<br/>✔ <strong>Dengeli boya akışı:</strong> Pürüzsüz ve eşit boya dağılımı<br/>✔ <strong>Dayanıklı yapılar:</strong> Endüstriyel kullanım için tasarlandı<br/>✔ <strong>Kolay bakım:</strong> Parça değişimi ve temizliği pratik</p></li></ul> </div><div> <p><strong>Boya Tabancası Çeşitleri</strong></p><p>HD Marine boya tabancaları kategorisinde şunlar bulunur:</p><p>✔ <strong>Airless Boya Tabancaları:</strong> Hava kullanmadan yüksek basınçla püskürtme<br/>✔ <strong>HVLP Boya Tabancaları:</strong> Düşük basınç ile yüksek transfer verimi<br/>✔ <strong>Püskürtme Tabancaları:</strong> Genel amaçlı profesyonel modeller<br/>✔ <strong>Aksesuarlı Tabancalar:</strong> Nozul setleri, dönüş başlıkları, filtreler</p><p>Her model, farklı uygulama ihtiyacına uygun olarak özel tasarlanmıştır.</p> </div>$h$, NULL, $h$H 827 | HD Marine$h$, $h$Boya tabancaları , boya veya kaplama malzemesini yüzeye püskürtmek için kullanılan profesyonel el aletleridir. Farklı tipleriyle (airless, HVLP, klasik…$h$, 'reviewed'),
